+                </Tooltip>
+              </TooltipProvider>
+            </TableHead>
+            <TableHead>{t('businessAdmin')}</TableHead>
+            <TableHead>{t('actions')}</TableHead>
+          </TableRow>
+        </TableHeader>
+        <TableBody>
+          {coinPools.map((pool, index) => (
+            <CoinPoolTableRow
+              key={pool.id}
