+  email: string | null;
+}
+
+interface BusinessAdminMultiSelectorProps {
+  value?: string[];
+  onValueChange: (value: string[]) => void;
+  placeholder?: string;
+  className?: string;
+  disabled?: boolean;
+  required?: boolean;
+  label?: string;
+}
+
+/**
+ * 業務管理員多選選擇器元件
+ * 用於多選業務管理員，支援搜尋
+ */
+export default function BusinessAdminMultiSelector({
+  value = [],
+  onValueChange,
+  placeholder,
+  className,
+  disabled = false,
+  required = false,
+  label
+}: BusinessAdminMultiSelectorProps) {
+  const tAdmin = useTranslations('admin');
+  const tCommon = useTranslations('common');
+
+  const [businessAdmins, setBusinessAdmins] = useState<BusinessAdmin[]>([]);
+  const [isLoading, setIsLoading] = useState(false);
+  const [error, setError] = useState<string | null>(null);
+  const defaultLabel = tAdmin('businessAdminSelector.label');
+  const defaultPlaceholder =
+    placeholder || tAdmin('businessAdminSelector.placeholder');
+
+  const fetchBusinessAdmins = async () => {
+    setIsLoading(true);
+    setError(null);
+    try {
+      const response = await fetch('/api/admin/users/business-admins');
+      const data = await response.json();
+      if (data.success) {
+        setBusinessAdmins(data.users);
+      } else {
+        setError(data.error || tAdmin('businessAdminSelector.error'));
+      }
+    } catch (err) {
+      console.error('Failed to fetch business admins:', err);
+      setError(tAdmin('businessAdminSelector.error'));
+    } finally {
+      setIsLoading(false);
+    }
+  };
+
+  useEffect(() => {
+    fetchBusinessAdmins();
+    // eslint-disable-next-line react-hooks/exhaustive-deps
+  }, []);
+
+  const options = businessAdmins.map((admin) => ({
+    value: admin.id,
+    label: admin.name || admin.email || 'No Name'
+  }));
+
+  const renderOption = (option: { value: string; label: string }) => {
+    const admin = businessAdmins.find((a) => a.id === option.value);
+    return (
+      <div className="flex flex-col w-full">
+        <span className="break-words whitespace-normal font-medium">
+          {option.label}
+        </span>
+        {admin?.email && (
+          <span className="text-xs text-gray-500 break-words whitespace-normal">
+            {admin.email}
+          </span>
+        )}
+      </div>
+    );
+  };
+
+  const renderSelectedItems = () => {
+    if (value.length === 0) {
+      return (
+        <span className="text-muted-foreground">{defaultPlaceholder}</span>
+      );
