+import { SessionProvider } from 'next-auth/react';
+import { getMessages } from 'next-intl/server';
+import { cookies } from 'next/headers';
+import { NextIntlClientProvider } from 'next-intl';
+
+import { auth } from '@/auth';
+import { Language } from '@/app/i18n';
+import CookieConsentBanner from '@/components/cookie-consent/cookie-banner';
+
+import { MixpanelProvider } from '../mixpanel-init';
+
+/**
+ * Canvas Layout
+ *
+ * Minimal layout for the canvas route group that excludes global navigation.
+ * This provides a full-screen canvas experience without header, sidebar, or footer.
+ *
+ * Includes:
+ * - NextIntlClientProvider (i18n)
+ * - SessionProvider (auth)
+ * - MixpanelProvider (analytics)
+ * - CookieConsentBanner (GDPR)
+ *
+ * Excludes:
+ * - Header (global top bar)
+ * - AppSidebar (global left bar)
+ * - SidebarProvider (sidebar context)
+ * - Footer (global footer)
+ *
+ * Note: Toaster is provided by the root app/layout.tsx (position: top-right)
+ */
+export default async function CanvasLayout({
+  children,
+  params: { locale }
+}: {
+  children: React.ReactNode;
+  params: { locale: Language };
+}) {
+  const cookieStore = await cookies();
+  const consentCookie = cookieStore.get('consent');
+  const initialConsent =
+    consentCookie === undefined ? null : consentCookie?.value === 'true';
+
+  const session = await auth();
+  const messages = await getMessages();
+
+  return (
+    <NextIntlClientProvider locale={locale} messages={messages}>
+      <SessionProvider session={session}>
+        <MixpanelProvider />
+        <div className="h-[100svh] w-screen overflow-hidden">
+          {children}
+        </div>
+        {/* Toaster is provided by root app/layout.tsx */}
+        <CookieConsentBanner initialConsent={initialConsent} />
+      </SessionProvider>
+    </NextIntlClientProvider>
+  );
+}
