+'use client';
+
+import { useState, useEffect } from 'react';
+import { useForm } from 'react-hook-form';
+import { zodResolver } from '@hookform/resolvers/zod';
+import { useTranslations } from 'next-intl';
+import { useRouter } from 'next/navigation';
+import { UserPlus } from 'lucide-react';
+import { toast } from 'sonner';
+
+import { CreateUserSchema, CreateUserFormValues } from '@/schemas';
+import {
+  Dialog,
+  DialogContent,
+  DialogDescription,
+  DialogHeader,
+  DialogTitle,
+  DialogTrigger
+} from '@/components/ui/dialog';
+import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
+import { Button } from '@/components/ui/button';
+import { Input } from '@/components/ui/input';
+import {
+  Form,
+  FormControl,
+  FormField,
+  FormItem,
+  FormLabel,
+  FormMessage
+} from '@/components/ui/form';
+import BusinessAdminSelector from '@/components/admin/business-admin-selector';
+import { UserSelector } from '@/components/admin/user-selector';
+import LoadingButton from '@/components/button/loading-button';
+import { createUser } from '@/actions/admin/create-user';
+import { addUserAsCoinPoolAdmin } from '@/actions/admin/coin-pool';
+
+type Mode = 'new' | 'existing';
+
+export default function CreateCoinPoolDialog() {
+  const t = useTranslations('admin.coinPoolManagement');
+  const tCreateUser = useTranslations('admin.users.createUser');
+  const router = useRouter();
+  const [open, setOpen] = useState(false);
+  const [mode, setMode] = useState<Mode>('new');
+  const [coinPoolAdminRoleId, setCoinPoolAdminRoleId] = useState<string>('');
+  const [isLoadingRoles, setIsLoadingRoles] = useState(false);
+  const [isSubmittingNew, setIsSubmittingNew] = useState(false);
+  const [isSubmittingExisting, setIsSubmittingExisting] = useState(false);
+
+  const form = useForm<CreateUserFormValues>({
+    resolver: zodResolver(CreateUserSchema),
+    defaultValues: {
+      name: '',
+      email: '',
+      password: '',
+      confirmPassword: '',
+      adminRoleId: '',
+      initialTokenAmount: undefined,
+      assignedBusinessAdmin: '',
+      coinPoolPermission: '',
+      organizationName: ''
+    }
+  });
+
+  const [existingUserId, setExistingUserId] = useState<string>('');
+  const [existingBusinessAdminId, setExistingBusinessAdminId] =
+    useState<string>('');
+
+  useEffect(() => {
+    if (open) {
+      setIsLoadingRoles(true);
+      fetch('/api/admin/roles/assignable')
+        .then((res) => res.json())
+        .then(
+          (data: {
+            success?: boolean;
+            roles?: Array<{ id: string; name: string }>;
+          }) => {
+            if (data.success && data.roles) {
+              const role = data.roles.find((r) => r.name === 'coin-pool-admin');
+              if (role) setCoinPoolAdminRoleId(role.id);
+            }
+          }
+        )
+        .finally(() => setIsLoadingRoles(false));
+    }
+  }, [open]);
+
+  const handleSubmitNew = async (values: CreateUserFormValues) => {
+    if (!coinPoolAdminRoleId) {
+      toast.error(tCreateUser('error.insufficientPermissions'));
+      return;
+    }
+    setIsSubmittingNew(true);
+    try {
+      const result = await createUser({
+        ...values,
+        adminRoleId: coinPoolAdminRoleId,
+        assignedBusinessAdmin: values.assignedBusinessAdmin || undefined,
+        initialTokenAmount: values.initialTokenAmount
+      });
+      if (result.error) {
+        toast.error(result.error);
+        return;
+      }
+      toast.success(tCreateUser('success.userCreated'));
+      setOpen(false);
+      form.reset();
+      router.refresh();
+    } finally {
+      setIsSubmittingNew(false);
+    }
+  };
+
+  const handleSubmitExisting = async (e: React.FormEvent) => {
+    e.preventDefault();
+    if (!existingUserId.trim() || !existingBusinessAdminId.trim()) {
+      toast.error(t('editAccess.error'));
+      return;
+    }
+    setIsSubmittingExisting(true);
+    try {
+      const result = await addUserAsCoinPoolAdmin(
+        existingUserId.trim(),
+        existingBusinessAdminId.trim()
+      );
+      if (result.error) {
+        toast.error(result.error);
+        return;
+      }
+      toast.success(result.success || 'Success');
+      setOpen(false);
+      setExistingUserId('');
+      setExistingBusinessAdminId('');
+      router.refresh();
+    } finally {
+      setIsSubmittingExisting(false);
+    }
+  };
+
+  return (
+    <Dialog open={open} onOpenChange={setOpen}>
+      <DialogTrigger asChild>
+        <Button>
+          <UserPlus className="mr-2 h-4 w-4" />
+          {t('createPool')}
+        </Button>
+      </DialogTrigger>
+      <DialogContent className="sm:max-w-[560px]">
+        <DialogHeader>
+          <DialogTitle>{t('createDialog.title')}</DialogTitle>
+          <DialogDescription>
+            {t('createDialog.modeNewUser')} /{' '}
+            {t('createDialog.modeExistingUser')}
+          </DialogDescription>
+        </DialogHeader>
+        <Tabs value={mode} onValueChange={(v) => setMode(v as Mode)}>
+          <TabsList>
+            <TabsTrigger value="new">{t('createDialog.newUser')}</TabsTrigger>
+            <TabsTrigger value="existing">
+              {t('createDialog.existingUser')}
+            </TabsTrigger>
+          </TabsList>
+          <TabsContent value="new">
+            <Form {...form}>
+              <form
+                onSubmit={form.handleSubmit(handleSubmitNew)}
+                className="space-y-4 mt-4"
+              >
+                <FormField
+                  control={form.control}
+                  name="name"
+                  render={({ field }) => (
+                    <FormItem>
+                      <FormLabel>
+                        {tCreateUser('form.name')}{' '}
+                        <span className="text-red-500">*</span>
+                      </FormLabel>
+                      <FormControl>
+                        <Input
+                          placeholder={tCreateUser('form.namePlaceholder')}
+                          {...field}
+                        />
+                      </FormControl>
+                      <FormMessage />
+                    </FormItem>
+                  )}
+                />
+                <FormField
+                  control={form.control}
+                  name="email"
+                  render={({ field }) => (
+                    <FormItem>
+                      <FormLabel>
+                        {tCreateUser('form.email')}{' '}
+                        <span className="text-red-500">*</span>
+                      </FormLabel>
+                      <FormControl>
+                        <Input
+                          type="email"
+                          placeholder={tCreateUser('form.emailPlaceholder')}
+                          {...field}
+                        />
+                      </FormControl>
+                      <FormMessage />
+                    </FormItem>
+                  )}
+                />
+                <FormField
+                  control={form.control}
+                  name="password"
+                  render={({ field }) => (
+                    <FormItem>
+                      <FormLabel>
+                        {tCreateUser('form.password')}{' '}
+                        <span className="text-red-500">*</span>
+                      </FormLabel>
+                      <FormControl>
+                        <Input type="password" {...field} />
+                      </FormControl>
+                      <FormMessage />
+                    </FormItem>
+                  )}
+                />
+                <FormField
+                  control={form.control}
+                  name="confirmPassword"
+                  render={({ field }) => (
+                    <FormItem>
+                      <FormLabel>
+                        {tCreateUser('form.confirmPassword')}{' '}
+                        <span className="text-red-500">*</span>
+                      </FormLabel>
+                      <FormControl>
+                        <Input type="password" {...field} />
+                      </FormControl>
+                      <FormMessage />
+                    </FormItem>
+                  )}
+                />
+                <FormField
+                  control={form.control}
+                  name="assignedBusinessAdmin"
+                  render={({ field }) => (
+                    <FormItem>
+                      <FormLabel>
+                        {tCreateUser('additionalFields.assignedBusinessAdmin')}{' '}
+                        <span className="text-red-500">*</span>
+                      </FormLabel>
+                      <FormControl>
+                        <BusinessAdminSelector
+                          value={field.value || ''}
+                          onValueChange={field.onChange}
+                          placeholder={tCreateUser(
+                            'additionalFields.assignedBusinessAdminPlaceholder'
+                          )}
+                        />
+                      </FormControl>
+                      <FormMessage />
+                    </FormItem>
+                  )}
+                />
+                <FormField
+                  control={form.control}
+                  name="initialTokenAmount"
+                  render={({ field }) => (
+                    <FormItem>
+                      <FormLabel>
+                        {tCreateUser('additionalFields.initialTokenAmount')}{' '}
+                        <span className="text-red-500">*</span>
+                      </FormLabel>
+                      <FormControl>
+                        <Input
+                          type="number"
+                          min={1}
+                          placeholder={tCreateUser(
+                            'additionalFields.initialTokenAmountPlaceholder'
+                          )}
+                          {...field}
+                          onChange={(e) =>
+                            field.onChange(
+                              e.target.value
+                                ? Number(e.target.value)
+                                : undefined
+                            )
+                          }
+                        />
+                      </FormControl>
+                      <FormMessage />
+                    </FormItem>
+                  )}
+                />
+                <div className="flex justify-end gap-2 pt-2">
+                  <Button
+                    type="button"
+                    variant="outline"
+                    onClick={() => setOpen(false)}
+                    disabled={isSubmittingNew}
+                  >
+                    {tCreateUser('button.cancel')}
+                  </Button>
+                  <LoadingButton
+                    type="submit"
+                    loading={isSubmittingNew || isLoadingRoles}
+                    disabled={!coinPoolAdminRoleId || isSubmittingNew}
+                  >
+                    {tCreateUser('button.create')}
+                  </LoadingButton>
+                </div>
+              </form>
+            </Form>
+          </TabsContent>
+          <TabsContent value="existing">
+            <form onSubmit={handleSubmitExisting} className="space-y-4 mt-4">
+              <div>
+                <label className="text-sm font-medium mb-2 block">
+                  {t('createDialog.coinPoolAdminLabel')}{' '}
+                  <span className="text-red-500">*</span>
+                </label>
+                <UserSelector
+                  value={existingUserId}
+                  onValueChange={(v) =>
+                    setExistingUserId(Array.isArray(v) ? v[0] ?? '' : v)
+                  }
+                  placeholder={t('search.namePlaceholder')}
+                />
+              </div>
+              <div>
+                <BusinessAdminSelector
+                  label={t('editAccess.businessAdminLabel')}
+                  value={existingBusinessAdminId}
+                  onValueChange={setExistingBusinessAdminId}
+                  placeholder={t('search.businessAdminPlaceholder')}
+                />
+              </div>
+              <div className="flex justify-end gap-2 pt-2">
+                <Button
+                  type="button"
+                  variant="outline"
+                  onClick={() => setOpen(false)}
+                  disabled={isSubmittingExisting}
+                >
+                  {tCreateUser('button.cancel')}
+                </Button>
+                <LoadingButton
+                  type="submit"
+                  loading={isSubmittingExisting}
+                  disabled={
+                    !existingUserId.trim() ||
+                    !existingBusinessAdminId.trim() ||
+                    isSubmittingExisting
+                  }
+                >
+                  {tCreateUser('button.create')}
+                </LoadingButton>
+              </div>
+            </form>
+          </TabsContent>
+        </Tabs>
+      </DialogContent>
+    </Dialog>
+  );
+}
