+    const rawUserIds = Array.isArray(body.userIds)
+      ? body.userIds
+      : typeof body.userId === 'string'
+      ? [body.userId]
+      : [];
+    const userIds = rawUserIds
+      .filter(
+        (id: unknown): id is string =>
+          typeof id === 'string' && Boolean(id.trim())
+      )
+      .map((id: string) => id.trim());
+
+    const coinPool = await prisma.user.findUnique({
+      where: { id: coinPoolId },
+      select: {
+        id: true,
+        userAdminRoles: {
+          select: {
+            adminRole: { select: { name: true } }
+          }
+        }
+      }
+    });
+
+    if (!coinPool) {
+      return NextResponse.json(
+        {
+          success: false,
+          error: ERROR_IDS.COIN_POOL_ACCESS_COIN_POOL_NOT_FOUND
+        },
+        { status: 404 }
+      );
+    }
+
+    const isCoinPoolAdmin = coinPool.userAdminRoles.some(
+      (ur) => ur.adminRole.name === 'coin-pool-admin'
+    );
+    if (!isCoinPoolAdmin) {
+      return NextResponse.json(
+        {
+          success: false,
+          error: ERROR_IDS.COIN_POOL_ACCESS_NOT_COIN_POOL
+        },
+        { status: 400 }
+      );
+    }
+
+    if (userIds.length > 0) {
+      const businessAdmins = await prisma.user.findMany({
+        where: {
+          id: { in: userIds },
+          userAdminRoles: {
+            some: {
+              adminRole: { name: 'business-admin' }
+            }
+          }
+        },
+        select: { id: true }
+      });
+      const validIds = new Set(businessAdmins.map((u) => u.id));
+      const invalidCount = userIds.filter(
+        (id: string) => !validIds.has(id)
+      ).length;
+      if (invalidCount > 0) {
+        return NextResponse.json(
+          {
+            success: false,
+            error: ERROR_IDS.COIN_POOL_ACCESS_INVALID_BUSINESS_ADMINS
+          },
+          { status: 400 }
+        );
+      }
+    }
+
+    await prisma.$transaction(async (tx) => {
+      await tx.coinPoolAccess.deleteMany({
+        where: { coinPoolId }
+      });
+      for (const userId of userIds) {
+        await tx.coinPoolAccess.create({
+          data: {
+            coinPoolId,
+            userId,
+            updateBy: user.id
+          }
+        });
+      }
+    });
+
+    return NextResponse.json({ success: true });
+  } catch (error) {
+    logger.error(
+      'Failed to update coin pool access',
+      error instanceof Error ? error : { cause: String(error) }
+    );
+    return NextResponse.json(
+      {
+        success: false,
+        error: ERROR_IDS.COIN_POOL_ACCESS_UPDATE_FAILED
+      },
+      { status: 500 }
+    );
+  }
