+'use client';
+
+import React from 'react';
+import { useLocale, useTranslations } from 'next-intl';
+import { FaUser } from 'react-icons/fa6';
+import { Ticket } from 'lucide-react';
+
+import { Language } from '@/app/i18n';
+import { Button } from '@/components/ui/button';
+import {
+  DropdownMenu,
+  DropdownMenuContent,
+  DropdownMenuItem,
+  DropdownMenuLabel,
+  DropdownMenuSeparator,
+  DropdownMenuTrigger
+} from '@/components/ui/dropdown-menu';
+import { Dialog, DialogContent, DialogTrigger } from '@/components/ui/dialog';
+import TrackedLink from '@/components/tracked-link';
+import LanguageSelect from '@/components/language-select';
+import { useFeatureFlags } from '@/lib/feature-flags';
+
+import { UserProfileIcon } from '../nav/user-profile-icon';
+import LogoutMenuItem from '../nav/logout-menu-item';
+import TokenBalanceButton from '../nav/token-balance-button';
+import InviteCodeForm from '../nav/invite-code/invite-code-form';
+
+import type { User } from 'next-auth';
+
+export function CanvasUserMenu({ sessionUser }: { sessionUser: User }) {
+  const t = useTranslations();
+  const locale = useLocale();
+  const [open, setOpen] = React.useState(false);
+  const { simpleCanvasMode } = useFeatureFlags();
+
+  if (!sessionUser) {
+    return null;
+  }
+
+  return (
+    <Dialog open={open} onOpenChange={setOpen}>
+      <DropdownMenu modal={false}>
+        <DropdownMenuTrigger asChild>
+          <Button
+            variant="ghost"
+            size="icon"
+            className="h-8 w-8 rounded-full"
+            data-testid="canvas-user-menu-trigger"
+          >
+            <UserProfileIcon
+              userImage={sessionUser.image || ''}
+              userName={sessionUser.name || ''}
+            />
+          </Button>
+        </DropdownMenuTrigger>
+        <DropdownMenuContent
+          className="w-64"
+          side="top"
+          align="start"
+          forceMount
+        >
+          <DropdownMenuLabel className="flex">
+            <TokenBalanceButton className="w-full max-w-none justify-between" />
+          </DropdownMenuLabel>
+          <DropdownMenuSeparator />
+          {!simpleCanvasMode && (
+            <>
+              <DropdownMenuItem className="flex">
+                <TrackedLink
+                  href="/profile"
+                  className="py-2 w-full inline-flex items-center font-bold"
+                >
+                  <FaUser className="w-4 h-4 mr-2" /> {t('My page')}
+                </TrackedLink>
+              </DropdownMenuItem>
+              <DropdownMenuSeparator />
+            </>
+          )}
+          <DialogTrigger asChild>
+            <DropdownMenuItem
+              className="py-3.5 cursor-pointer items-center font-bold"
+              onClick={() => setOpen(true)}
+              data-testid="canvas-use-invite-code-button"
+            >
+              <Ticket className="w-4 h-4 mr-2" />
+              {t('Use invite code')}
+            </DropdownMenuItem>
+          </DialogTrigger>
+          <DropdownMenuSeparator />
+          <DropdownMenuLabel className="py-1 flex justify-between items-center gap-2 font-bold">
+            <span className="whitespace-nowrap">{t('Language')}</span>
+            <LanguageSelect lang={locale as Language} />
+          </DropdownMenuLabel>
+          <DropdownMenuSeparator />
+          <LogoutMenuItem />
+        </DropdownMenuContent>
+      </DropdownMenu>
+
+      <DialogContent>
+        <InviteCodeForm onSuccess={() => setOpen(false)} />
+      </DialogContent>
+    </Dialog>
+  );
+}
